CREATE TABLE "accounts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "currency_code" TEXT NOT NULL DEFAULT 'INR', "icon_code_point" INTEGER NULL, "color_value" INTEGER NULL, "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "archived_at" INTEGER NULL, "display_order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "app_settings" ("id" INTEGER NOT NULL, "currency_code" TEXT NOT NULL DEFAULT 'INR', "default_account_id" TEXT NULL REFERENCES accounts (uuid), "theme_mode" TEXT NOT NULL DEFAULT 'system', "app_lock_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("app_lock_enabled" IN (0, 1)), "document_retention_days" INTEGER NULL, "default_reminder_days" INTEGER NOT NULL DEFAULT 1, "sheets_backup_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("sheets_backup_enabled" IN (0, 1)), "setup_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("setup_completed" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "categories" ("category_id" TEXT NOT NULL, "name" TEXT NOT NULL, "icon_code_point" INTEGER NOT NULL, "color_value" INTEGER NULL, "kind" TEXT NOT NULL, "origin" TEXT NOT NULL, "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "parent_category_id" TEXT NULL REFERENCES categories (category_id), "display_order" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("category_id"));
CREATE TABLE "financial_transactions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NOT NULL UNIQUE, "kind" TEXT NOT NULL, "category_id" TEXT NULL REFERENCES categories (category_id), "reverses_transaction_id" TEXT NULL REFERENCES financial_transactions (uuid), "related_transaction_id" TEXT NULL REFERENCES financial_transactions (uuid), "source_account_id" TEXT NULL REFERENCES accounts (uuid), "destination_account_id" TEXT NULL REFERENCES accounts (uuid), "refund_account_id" TEXT NULL REFERENCES accounts (uuid), "amount_minor_units" INTEGER NOT NULL, "currency_code" TEXT NOT NULL DEFAULT 'INR', "description" TEXT NULL, "notes" TEXT NULL, "payment_channel" TEXT NOT NULL, "occurred_at" INTEGER NOT NULL, "status" TEXT NOT NULL, "source" TEXT NOT NULL, "adjustment_reason" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "sync_revision" INTEGER NOT NULL DEFAULT 0, "sync_status" TEXT NOT NULL, CHECK (amount_minor_units > 0));
CREATE TABLE "ledger_accounts" ("ledger_account_id" TEXT NOT NULL, "kind" TEXT NOT NULL, "user_account_id" TEXT NULL UNIQUE REFERENCES accounts (uuid), "category_id" TEXT NULL REFERENCES categories (category_id), "is_system" INTEGER NOT NULL DEFAULT 0 CHECK ("is_system" IN (0, 1)), "normal_balance" TEXT NOT NULL, "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), PRIMARY KEY ("ledger_account_id"));
CREATE TABLE "notifications" ("id" TEXT NOT NULL, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "message" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "is_read" INTEGER NOT NULL DEFAULT 0 CHECK ("is_read" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "postings" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NOT NULL UNIQUE, "transaction_id" INTEGER NOT NULL REFERENCES financial_transactions (id), "ledger_account_id" TEXT NOT NULL REFERENCES ledger_accounts (ledger_account_id), "direction" TEXT NOT NULL, "amount_minor_units" INTEGER NOT NULL, "currency_code" TEXT NOT NULL DEFAULT 'INR', "posting_date" INTEGER NOT NULL, CHECK (amount_minor_units > 0));
CREATE TABLE "transaction_history" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NOT NULL UNIQUE, "transaction_id" INTEGER NOT NULL REFERENCES financial_transactions (id), "changed_at" INTEGER NOT NULL, "change_kind" TEXT NOT NULL, "before_snapshot" TEXT NULL, "after_snapshot" TEXT NULL);
CREATE INDEX categories_kind ON categories (kind);
CREATE INDEX financial_transactions_kind ON financial_transactions (kind);
CREATE INDEX financial_transactions_occurred_at ON financial_transactions (occurred_at);
CREATE INDEX financial_transactions_related ON financial_transactions (related_transaction_id);
CREATE INDEX financial_transactions_reverses ON financial_transactions (reverses_transaction_id);
CREATE UNIQUE INDEX ledger_accounts_category_kind ON ledger_accounts (category_id, kind);
